ancelar a compra, e quando compra foi estornada pela situação da bandeira "aproveitaram" para pedir cancelamento.\nestavam insatisfeitos pela condição de pagamento, ouviram sobre cartao, fizeram no boleto e acharam ruim a questao de "ter mais juros"\naparentemente namorada que resolve as coisas dele, ele repetiu as mesmas coisas da conversa da namorada.	Finalizado	Cancelado	Jurídico	t	\N	\N	f	[{"url": "00000000-0000-0000-0000-0000000a1a11/termos/52ba9f6f-7acc-4972-aa82-2585a55ab134_1786117654695_Termo_de_cancelamento_assinado.pdf", "name": "Termo de cancelamento assinado.pdf", "type": "termo_assinado", "uploadedAt": "2026-08-07T15:47:35.743Z"}]	2026-08-19 20:07:27.043+00	2026-08-03 14:38:07.97+00	2026-08-19 20:07:20.61015+00	["Ajuste financeiro AC (pré-cancelamento)"]	0	[]	00000000-0000-0000-0000-0000000a1a11	t	t	\N	0	0	\N	\N	\N	{"conciliadoAt": "2026-08-19T20:07:27.016Z", "conciliadoPorId": "10161ea9-4d8a-4a2a-add6-b6ddd4a482eb", "conciliadoBoletos": true, "conciliadoPorNome": "Gabriele Almeida"}	2000	1	0	{"pixKey": "eliezerfernandogas par6@gmail.com", "createdAt": "2026-08-07T15:48:35.272Z", "pixKeyType": "Email", "totalValue": 2000, "installments": [{"date": "2026-08-25", "value": 1000, "lancadoAt": "2026-08-13T20:27:11.205Z", "lancadoLog": [{"at": "2026-08-13T20:27:11.205Z", "action": "marcou", "byName": "Arnô Felipe Santos Assis", "byUserId": "e940197f-421f-4f60-a895-976a3204273a"}], "lancadoPorNome": "Arnô Felipe Santos Assis", "lancadoPorUserId": "e940197f-421f-4f60-a895-976a3204273a", "lancadoParaPagamento": true}, {"date": "2026-09-25", "value": 1000, "lancadoAt": "2026-08-13T20:27:12.893Z", "lancadoLog": [{"at": "2026-08-13T20:27:12.893Z", "action": "marcou", "byName": "Arnô Felipe Santos Assis", "byUserId": "e940197f-421f-4f60-a895-976a3204273a"}], "lancadoPorNome": "Arnô Felipe Santos Assis", "lancadoPorUserId": "e940197f-421f-4f60-a895-976a3204273a", "lancadoParaPagamento": true}]}	[{"id": "e8a0b3e0-967d-45c6-8909-602a12efa34f", "text": "https://app.zap